<script setup lang="ts">
import PublicStreamText from '../components/PublicStreamText.vue'
import {ref,watch,onMounted} from 'vue'
import {Sparkles,Check,Square} from 'lucide-vue-next'
import {useWorld} from './store'
import {worldApi} from './api'
import {worldMutation,clearWorldMutation} from './mutation-intent'
import type {WorldTurn} from './types'
import {useRequestScope} from '../platform/request-scope'
const props=defineProps<{turnId?:string}>(),emit=defineEmits<{accepted:[]}>(),store=useWorld(),capture=useRequestScope(),count=ref(1),custom=ref(false),wish=ref(''),selected=ref<WorldTurn|null>(null),turnId=ref(props.turnId||''),busy=ref(false),error=ref(''),acceptCount=ref(1)
let readVersion=0
async function load(){const version=++readVersion,worldId=store.world?.id,id=turnId.value;if(!id||!worldId)return;const scope=capture(),valid=()=>scope.valid()&&version===readVersion&&worldId===store.world?.id&&id===turnId.value;try{const result=await worldApi<WorldTurn>('/worlds/'+worldId+'/turns/'+id);if(valid()){selected.value=result;acceptCount.value=result.chapters.length||1}}catch(e){if(valid())error.value=(e as Error).message}}
async function write(){if(!store.world||!store.line)return;const scope=capture();busy.value=true;error.value='';try{const slot='write:'+store.world.id+':'+store.line.id;const result=await worldMutation<{taskId:string;turnId:string}>(slot,'/worlds/'+store.world.id+'/lines/'+store.line.id+'/write',{chapterCount:count.value,instruction:wish.value,expectedCheckpointId:store.line.headCheckpointId},scope.valid);if(!scope.valid())return;turnId.value=result.turnId;void store.watchTask(result.taskId);await clearWorldMutation(slot,scope.valid);await load()}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function accept(){if(!store.world||!store.line||!selected.value||selected.value.status==='historical')return;const scope=capture();busy.value=true;error.value='';try{const slot='accept:'+store.world.id+':'+selected.value.id;await worldMutation(slot,'/worlds/'+store.world.id+'/turns/'+selected.value.id+'/accept',{chapterCount:acceptCount.value,expectedCheckpointId:store.line.headCheckpointId},scope.valid);if(!scope.valid())return;await store.reloadHead();await clearWorldMutation(slot,scope.valid);if(scope.valid())emit('accepted')}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
watch(()=>props.turnId,id=>{turnId.value=id||'';selected.value=null;error.value='';acceptCount.value=1;void load()});watch(()=>[store.task?.state,store.task?.persistenceState],()=>void load());watch(()=>store.task?.result.chapterIndex,()=>void load());onMounted(load)
</script>
<template><div class="world-write-panel"><template v-if="!turnId"><h2>接下来，写几章？</h2><div class="world-chapter-choices"><button v-for="n in [1,3,5]" :key="n" :class="{selected:!custom&&count===n}" @click="count=n;custom=false">{{n}} 章</button><button :class="{selected:custom}" @click="custom=true">自定义</button></div><label v-if="custom">章节数<input v-model.number="count" type="number" min="1" max="10"></label><label>想让故事怎样发展？<textarea v-model="wish" maxlength="1500" placeholder="选填"></textarea></label><button class="primary world-full-button" :disabled="busy||store.running||count<1||count>10" @click="write"><Sparkles :size="18"/>开始写作<span>{{count}} 章</span></button></template><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="turnId&&store.running" class="world-writing-status" role="status"><span class="world-pulse"></span><template v-if="store.recovering">正在恢复保存…</template><template v-else>正在写第 {{store.task?.result.chapterIndex||1}} / {{store.task?.result.chapterCount||count}} 章</template><button class="icon-button" aria-label="停止写作" @click="store.cancel"><Square :size="17"/></button></div><article v-for="c in selected?.chapters||[]" :key="c.index" class="world-candidate"><small>第 {{c.index}} 章</small><h2>{{c.title}}</h2><div class="world-prose">{{c.text}}</div></article><div v-if="store.running&&store.task?.stream.text" class="world-prose world-live-prose"><PublicStreamText :text="store.task.stream.text" :content-id="store.task.stream.contentId||store.task.id" :stream-version="store.task.stream.streamVersion||1"/><span class="world-caret"></span></div><template v-if="selected&&!store.running"><p v-for="warning in selected.warnings" :key="warning" class="hint" role="status">{{warning}}</p><p v-if="selected.status==='draft'" class="hint">这次未完成，已收到的文字仍可阅读。</p><p v-if="selected.status==='historical'" class="hint">从备份恢复 · 已收到的正文，尚未保存到世界线</p><div v-if="['draft','historical'].includes(selected.status)&&selected.draftText&&selected.draftText!==selected.chapters.at(-1)?.text" class="world-prose">{{selected.draftText}}</div><div v-if="selected.chapters.length&&!selected.acceptedCount&&selected.status!=='historical'" class="world-accept"><label>保存到世界线<select v-model.number="acceptCount"><option v-for="n in selected.chapters.length" :key="n" :value="n">{{n===selected.chapters.length?'全部 '+n+' 章':'前 '+n+' 章'}}</option></select></label><button class="primary" :disabled="busy" @click="accept"><Check :size="18"/>保存并继续游玩</button></div><p v-else-if="selected.acceptedCount" class="hint">已保存前 {{selected.acceptedCount}} 章</p></template></div></template>
